import { normalize } from './normalize.mjs';
export const tagLabel = value => normalize(value);

export const normalizeTags = (values) => {
  return values
    .map(normalize)
    .filter((value) => value !== '')
    .filter((value, index, self) => self.indexOf(value) === index)
    .sort();
};

